package dev.celerbi.easyfarmersdelightcompat.compat.jade;
import dev.celerbi.easyfarmersdelightcompat.EasyFarmersDelightCompat;import dev.celerbi.easyfarmersdelightcompat.blockentity.CutterBlockEntity;import dev.celerbi.easyfarmersdelightcompat.integration.CutterLogVariant;import java.util.ArrayList;import java.util.List;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.nbt.CompoundTag;import net.minecraft.nbt.ListTag;import net.minecraft.nbt.Tag;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.Item;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.block.Block;import snownee.jade.api.BlockAccessor;import snownee.jade.api.IBlockComponentProvider;import snownee.jade.api.IServerDataProvider;import snownee.jade.api.ITooltip;import snownee.jade.api.config.IPluginConfig;import snownee.jade.api.ui.IDisplayHelper;import snownee.jade.api.ui.IElement;import snownee.jade.api.ui.IElementHelper;
public enum CutterJadeProvider implements IBlockComponentProvider,IServerDataProvider<BlockAccessor>{INSTANCE;private static final ResourceLocation UID=ResourceLocation.fromNamespaceAndPath(EasyFarmersDelightCompat.MOD_ID,"cutter_info");private static final String VARIANT="Variant",TOOL="Tool",OUTPUTS="Outputs",STACK="Stack",COUNT="Count";
 public void appendServerData(CompoundTag d,BlockAccessor a){if(!(a.getBlockEntity() instanceof CutterBlockEntity c))return;d.putString(VARIANT,BuiltInRegistries.BLOCK.getKey(c.logVariant()).toString());d.remove(TOOL);ItemStack tool=c.toolHandler().getStackInSlot(0);if(!tool.isEmpty())d.putString(TOOL,BuiltInRegistries.ITEM.getKey(tool.getItem()).toString());d.remove(OUTPUTS);List<OutputEntry> outs=aggregate(c);if(!outs.isEmpty()){ListTag l=new ListTag();for(var e:outs){CompoundTag x=new CompoundTag();x.put(STACK,e.stack.save(a.getLevel().registryAccess()));x.putInt(COUNT,e.count);l.add(x);}d.put(OUTPUTS,l);}}
 public void appendTooltip(ITooltip t,BlockAccessor a,IPluginConfig cfg){CompoundTag d=a.getServerData();String v=d.getString(VARIANT);if(!v.isEmpty()){ResourceLocation id=ResourceLocation.tryParse(v);Block b=id==null?null:BuiltInRegistries.BLOCK.get(id);if(b!=null)t.add(Component.translatable("jade.easyfarmersdelightcompat.cutter.variant",Component.translatable(CutterLogVariant.translationKey(b))));}String ts=d.getString(TOOL);if(!ts.isEmpty()){ResourceLocation id=ResourceLocation.tryParse(ts);Item item=id==null?null:BuiltInRegistries.ITEM.get(id);if(item!=null)t.add(Component.translatable("jade.easyfarmersdelightcompat.cutter.tool",new ItemStack(item).getHoverName()));}if(d.contains(OUTPUTS,Tag.TAG_LIST)){ListTag l=d.getList(OUTPUTS,Tag.TAG_COMPOUND);IElementHelper el=IElementHelper.get();IDisplayHelper display=IDisplayHelper.get();for(int i=0;i<l.size();i++){CompoundTag x=l.getCompound(i);ItemStack s=ItemStack.parseOptional(a.getLevel().registryAccess(),x.getCompound(STACK));int count=Math.max(0,x.getInt(COUNT));if(s.isEmpty()||count<=0)continue;Component line=Component.literal(display.humanReadableNumber(count,"",false,null)).append("× ").append(display.stripColor(s.getHoverName()));List<IElement> row=List.of(el.smallItem(s).clearCachedMessage(),el.text(line).message(null));t.add(row);}}}
 private static List<OutputEntry> aggregate(CutterBlockEntity c){List<OutputEntry> out=new ArrayList<>();for(int slot=0;slot<c.outputHandler().getSlots();slot++){ItemStack s=c.outputHandler().getStackInSlot(slot);if(s.isEmpty())continue;boolean merged=false;for(int i=0;i<out.size();i++){var e=out.get(i);if(ItemStack.isSameItemSameComponents(e.stack,s)){out.set(i,new OutputEntry(e.stack,e.count+s.getCount()));merged=true;break;}}if(!merged)out.add(new OutputEntry(s.copyWithCount(1),s.getCount()));}return out;}public ResourceLocation getUid(){return UID;}private record OutputEntry(ItemStack stack,int count){}
}
